'use strict';
const courierNav=[['offers','Yangi takliflar','bag'],['active','Faol buyurtma','pin'],['history','Yetkazishlar tarixi','orders'],['earnings','Daromadlar','wallet'],['profile','Profil','users']];
let courierState,courierId='',courierPage='offers',courierPeriod='7',courierBranch='all',courierError='',courierBusy=false,courierReturnFocus=null;
try{courierState=courierInitialize();courierId=sessionStorage.getItem('lazzat-courier-id')||courierState.couriers[0]?.id||'';}catch(error){courierError=error.message;}
const courierPerson=()=>courierState?.couriers?.find(c=>c.id===courierId&&c.active);
const courierTotal=o=>o.items.reduce((sum,i)=>sum+i.price*i.qty,0);
const courierBranchInfo=id=>courierState.branches.find(b=>b.id===id);
const courierButton=(label,action,id='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-id="${esc(id)}" ${courierBusy?'disabled':''}>${label}</button>`;
const courierEmpty=text=>`<div class="panel"><div class="empty">${icon('bag')}<br>${text}</div></div>`;
function courierToast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(courierToast.timer);courierToast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function courierDate(value){return new Date(value).toLocaleString('uz-UZ',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});}
function courierSince(){if(courierPeriod==='all')return 0;const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(Number(courierPeriod)||7)+1);return +d;}
function courierDone(){return courierHistory(courierState,courierId).filter(o=>o.delivery.deliveredAt>=courierSince());}
function courierPeriodFilter(){return `<div class="filter-row"><select id="courier-period" aria-label="Daromad va tarix davri">${[['1','Bugun'],['7','So‘nggi 7 kun'],['30','So‘nggi 30 kun'],['all','Barcha vaqt']].map(([id,label])=>`<option value="${id}" ${courierPeriod===id?'selected':''}>${label}</option>`).join('')}</select></div>`;}
function courierStats(){const today=new Date();today.setHours(0,0,0,0);const delivered=courierHistory(courierState,courierId).filter(o=>o.delivery.deliveredAt>=+today);return `<div class="stats">${[['Bugungi daromad',money(delivered.reduce((s,o)=>s+o.delivery.fee,0)+(courierState.courierExtras||[]).filter(e=>e.courierId===courierId&&e.at>=+today).reduce((sum,e)=>sum+e.amount,0)),'so‘m','Faqat yakunlangan yetkazishlar','wallet'],['Bugun yetkazilgan',delivered.length,'ta','Kuryer tasdiqlagan buyurtmalar','check'],['Faol buyurtma',courierActiveOrders(courierState,courierId).length,'ta','Bir vaqtda bitta buyurtma','pin'],['Tayyor takliflar',courierState.orders.filter(o=>o.status==='ready'&&!o.delivery&&deliveryReady(o)).length,'ta','Manzil va haqi kiritilgan','bag']].map(([t,v,u,n,i])=>`<div class="stat"><div class="stat-top">${t}<div class="stat-icon">${icon(i)}</div></div><strong>${v} <small>${u}</small></strong><div class="stat-bottom">${n}</div></div>`).join('')}</div>`;}
function courierCard(o,mode){const branch=courierBranchInfo(o.branch);const owned=o.delivery?.courierId===courierId;const stage=deliveryStage(o);const fee=o.delivery?.fee??o.deliveryFee;const canClaim=courierPerson()?.online&&!courierActiveOrders(courierState,courierId).length&&deliveryReady(o);return `<article class="courier-card"><div class="order-head"><div><strong>#${esc(o.id.slice(0,12))}</strong> ${o.courierDemo?'<span class="tag">Sinov</span>':''}<div style="margin-top:8px">${deliveryBadge(o)||'<span class="tag success">Olib ketishga tayyor</span>'}</div></div><div class="reward">${Number.isFinite(fee)?money(fee):'—'} <small>so‘m</small></div></div><div class="route-stops"><div class="route-stop"><span class="stop-marker">${icon('bag')}</span><div><small>RESTORANDAN OLISH</small><strong>${esc(branch?.name||'Noma’lum filial')}</strong><br><span class="metric-note">${esc(branch?.address||'Manzil kiritilmagan')}</span></div></div><div class="route-stop"><span class="stop-marker">${icon('pin')}</span><div><small>YETKAZISH MANZILI</small><strong>${esc(o.deliveryAddress||'Sotuvchi yetkazish manzilini kiritishi kerak')}</strong></div></div></div>${owned?`<ul class="order-items">${o.items.map(i=>`<li><b>${i.qty}×</b> ${esc(i.name)}</li>`).join('')}</ul><p class="metric-note">${esc(o.customer)}${/^[+0-9 ()-]{9,25}$/.test(o.phone||'')?` · <a class="phone" href="tel:${esc(o.phone.replace(/[^+0-9]/g,''))}">${esc(o.phone)}</a>`:''}</p>`:''}<div class="card-meta"><span>${esc(o.payment)} · Buyurtma: ${money(courierTotal(o))} so‘m</span><span>${courierDate(o.created)}</span></div>${o.deliveryNote?`<div class="notice">${esc(o.deliveryNote)}</div>`:''}${o.delivery?.issue?`<div class="notice">Belgilangan muammo: ${esc(o.delivery.issue)}</div>`:''}${mode==='active'?`<div class="delivery-progress"><span class="done">1. Biriktirildi</span><span class="${stage==='picked_up'?'done':''}">2. Olib ketildi</span><span>3. Yetkazildi</span></div>`:''}<div class="card-actions">${mode==='offer'?`<button type="button" class="btn primary" data-action="claim" data-id="${esc(o.id)}" ${!canClaim||courierBusy?'disabled':''}>${!deliveryReady(o)?'Yetkazish ma’lumoti yetishmaydi':!courierPerson()?.online?'Avval liniyaga chiqing':courierActiveOrders(courierState,courierId).length?'Faol buyurtmani yakunlang':'Buyurtmani olish'}</button>`:mode==='active'?`${courierButton(stage==='assigned'?'Restorandan oldim':'Yetkazdim',stage==='assigned'?'confirm-pickup':'confirm-deliver',o.id,'primary')}${stage==='assigned'?courierButton('Qaytarish','confirm-release',o.id):''}${courierButton('Muammo','issue',o.id,'danger')}`:courierButton('Tafsilot','detail',o.id)}${owned&&o.deliveryAddress?`<a class="btn" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(o.deliveryAddress)}" target="_blank" rel="noopener noreferrer">${icon('pin')} Xaritada ochish</a>`:''}</div><p class="metric-note" style="margin-top:14px">${mode==='history'?'Yetkazilgan: '+courierDate(o.delivery.deliveredAt):'Kuryer haqi — demo hisob. Mijozdan alohida undirilmaydi.'}</p></article>`;}
function courierOffers(){const person=courierPerson();const list=courierState.orders.filter(o=>o.status==='ready'&&!o.delivery&&(courierBranch==='all'||o.branch===courierBranch)).sort((a,b)=>a.created-b.created);return `<section class="route-hero"><div><span class="tag">3-bosqich · Kuryer</span><h1>Yo‘lga tayyormisiz, ${esc(person.name.split(' ')[0])}?</h1><p>Tayyor buyurtmani oling, restorandan olib keting va mijozga yetkazing. Barcha bosqichlar bitta joyda.</p></div><div class="hero-bike" aria-hidden="true">🚲</div></section>${courierStats()}${!person.online?'<div class="online-hint"><strong>Hozir liniyada emassiz.</strong> Yangi buyurtma olish uchun yuqoridagi “Liniyaga chiqish” tugmasini bosing.</div>':''}<div class="page-title"><div><h1>Yangi takliflar</h1><p class="subtitle">Sotuvchi “Tayyor” deb belgilagan buyurtmalar.</p></div>${courierButton('+ Demo buyurtma','demo','','soft')}</div><div class="filter-row"><select id="courier-branch" aria-label="Takliflar filiali"><option value="all">Barcha filiallar</option>${courierState.branches.map(b=>`<option value="${esc(b.id)}" ${courierBranch===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select>${courierButton('Yangilash','refresh')}</div>${list.length?`<div class="courier-grid">${list.map(o=>courierCard(o,'offer')).join('')}</div>`:courierEmpty('Hozircha tayyor buyurtmalar yo‘q. Sotuvchi panelida buyurtmani tayyorlang yoki demo buyurtma yarating.')}`;}
function courierActiveView(){const list=courierActiveOrders(courierState,courierId);return `<div class="page-title"><div><h1>Faol buyurtma</h1><p class="subtitle">Olib ketish va yetkazish bosqichlarini tasdiqlang.</p></div>${courierButton('Yangilash','refresh')}</div>${list.length?`<div class="courier-grid">${list.map(o=>courierCard(o,'active')).join('')}</div>`:courierEmpty('Faol buyurtma yo‘q. Yangi takliflardan buyurtma oling.')}`;}
function courierHistoryView(){const list=courierDone();return `<div class="page-title"><div><h1>Yetkazishlar tarixi</h1><p class="subtitle">Faqat siz yetkazgan buyurtmalar.</p></div>${courierButton('CSV yuklash','export')}</div>${courierPeriodFilter()}${list.length?`<div class="courier-grid">${list.map(o=>courierCard(o,'history')).join('')}</div>`:courierEmpty('Tanlangan davrda yakunlangan yetkazishlar yo‘q.')}`;}
function courierEarnings(){const list=courierDone(),earned=list.reduce((s,o)=>s+o.delivery.fee,0),cash=list.reduce((s,o)=>s+(o.delivery.cashCollected||0),0);return `<div class="page-title"><div><h1>Daromadlar</h1><p class="subtitle">Yetkazish haqi va qabul qilingan naqd to‘lovlar.</p></div>${courierButton('CSV yuklash','export')}</div>${courierPeriodFilter()}<div class="stats">${[['Hisoblangan daromad',money(earned),'so‘m'],['Yetkazishlar',list.length,'ta'],['O‘rtacha haq',money(list.length?Math.round(earned/list.length):0),'so‘m'],['Qabul qilingan naqd',money(cash),'so‘m']].map(([t,v,u])=>`<div class="stat"><div class="stat-top">${t}</div><strong>${v} <small>${u}</small></strong></div>`).join('')}</div><div class="notice">Naqd summa — mijozdan qabul qilingan buyurtma puli; kuryer daromadi emas. Bu demo hisob, pul yechish va haqiqiy hisob-kitob ulanmagan.</div><div class="panel table-wrap"><h2>Yetkazish haqlari</h2><table><thead><tr><th>BUYURTMA</th><th>YETKAZILGAN VAQT</th><th>KURYER HAQI</th><th>QABUL QILINGAN NAQD</th></tr></thead><tbody>${list.map(o=>`<tr><td>#${esc(o.id.slice(0,12))}</td><td>${courierDate(o.delivery.deliveredAt)}</td><td><strong>${money(o.delivery.fee)} so‘m</strong></td><td>${money(o.delivery.cashCollected||0)} so‘m</td></tr>`).join('')}</tbody></table>${list.length?'':courierEmpty('Daromadlar hali yo‘q.')}</div>`;}
function courierProfile(){const c=courierPerson();return `<div class="page-title"><div><h1>Kuryer profili</h1><p class="subtitle">Demo profil ma’lumotlarini boshqaring.</p></div></div><form id="courier-profile" class="panel"><div class="profile-header"><div class="avatar">${esc(c.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}</div><div><h2>${esc(c.name)}</h2><span class="tag ${c.online?'success':'warning'}">${c.online?'Liniyada':'Liniyada emas'}</span></div></div><div class="form-row">${courierField('Ism va familiya','name',c.name)}${courierField('Telefon','phone',c.phone,'tel','required pattern="[+0-9 ()-]{9,25}"')}</div><div class="field"><label for="courier-vehicle">Transport</label><select id="courier-vehicle" name="vehicle">${['Velosiped','Skuter','Avtomobil','Piyoda'].map(v=>`<option ${c.vehicle===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="notice">Yuqoridagi kuryer tanlovi demo uchun. Haqiqiy login, SMS tasdiqlash va qurilmalararo sinxronlash hali ulanmagan. Xarita bo‘limida GPSni yoqishingiz mumkin.</div><div class="form-error" role="alert"></div><button type="submit" class="btn primary">Saqlash</button></form>`;}
function courierField(label,name,value='',type='text',attrs='required maxlength="80"'){return `<div class="field"><label for="courier-${name}">${label}</label><input id="courier-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function courierRender(){if(courierError){$('#main').innerHTML=`<div class="notice">${esc(courierError)}</div>`;return;}const c=courierPerson();$('#sidebar').innerHTML=`<a class="brand" href="courier.html" style="text-decoration:none"><div class="brand-mark brand-logo"><img src="assets/lazzat-logo.png" width="36" height="36" alt="Lazzat"></div><div class="brand-text">lazzat<small>KURYER UCHUN</small></div></a><div class="restaurant"><div class="avatar">${icon('pin')}</div><div><strong>${esc(c?.name||'Kuryer tanlang')}</strong><small>${esc(c?.vehicle||'Demo kabinet')}</small></div></div><div class="nav-label">YETKAZISH BOSHQARUVI</div><nav aria-label="Kuryer menyusi">${courierNav.map(([id,t,i])=>`<button type="button" data-action="nav" data-id="${id}" title="${t}" class="${courierPage===id?'active':''}" ${courierPage===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><span class="tag">3-bosqich · Demo</span><a href="seller.html">Sotuvchi paneli ↗</a><a href="owner.html">Biznes egasi paneli ↗</a><p>Sinov ma’lumotlari shu brauzerda saqlanadi.</p></div>`;$('#topbar').innerHTML=`<div class="crumb">Kuryer kabineti <span>/</span><strong>${courierNav.find(n=>n[0]===courierPage)[1]}</strong></div><div class="top-actions"><label class="demo-identity">Demo kuryer <select id="courier-person" aria-label="Demo kuryerni tanlash"><option value="">Kuryer tanlang</option>${courierState.couriers.filter(c=>c.active).map(p=>`<option value="${esc(p.id)}" ${courierId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${c?`<div class="online-control"><span class="tag ${c.online?'success':'warning'}">${c.online?'● Liniyada':'● Liniyada emas'}</span>${courierButton(c.online?'Dam olish':'Liniyaga chiqish','online','','primary')}</div>`:''}</div>`;$('#main').innerHTML=c?({offers:courierOffers,active:courierActiveView,history:courierHistoryView,earnings:courierEarnings,profile:courierProfile})[courierPage]():courierEmpty('Yuqoridan faol demo kuryerni tanlang.');}
function courierModal(title,body,form='',id=''){courierReturnFocus=document.activeElement;$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${courierButton('✕','close','','small')}</div>${form?`<form id="${form}" data-id="${esc(id)}">`:''}${body}${form?'<div class="form-error" role="alert"></div><div class="dialog-actions">'+courierButton('Bekor qilish','close')+'<button type="submit" class="btn primary">Tasdiqlash</button></div></form>':''}`;$('#overlay').hidden=false;$('#dialog').focus();}
function courierClose(){$('#overlay').hidden=true;courierReturnFocus?.focus();}
async function courierRun(action,id,payload={}){if(courierBusy)throw Error('Amal bajarilmoqda.');courierBusy=true;try{courierState=await courierTransaction(courierId,action,id,payload);courierError='';return true;}finally{courierBusy=false;}}
function courierExport(){const rows=[['Buyurtma','Sana','Kuryer haqi','Qabul qilingan naqd'],...courierDone().map(o=>[o.id,new Date(o.delivery.deliveredAt).toISOString(),o.delivery.fee,o.delivery.cashCollected||0])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(/^[=+@\-]/.test(String(v))?"'"+v:v).replace(/"/g,'""')+'"').join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='lazzat-kuryer-hisobot.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||courierBusy)return;const {action,id}=b.dataset;try{if(action==='nav'){courierPage=id;courierState=courierRead();courierRender();return;}if(action==='close'){courierClose();return;}if(action==='refresh'){courierState=courierRead();courierRender();courierToast('Ma’lumotlar yangilandi.');return;}if(action==='export'){courierExport();return;}if(action==='online'){await courierRun('online','',{online:!courierPerson().online});courierRender();return;}if(action==='demo'){await courierRun('demo');courierPage='offers';courierRender();courierToast('Sinov buyurtma yaratildi.');return;}if(action==='claim'){await courierRun('claim',id);courierPage='active';courierRender();courierToast('Buyurtma sizga biriktirildi.');return;}const o=courierState.orders.find(o=>o.id===id&&o.delivery?.courierId===courierId);if(!o)throw Error('Sizga biriktirilgan buyurtma topilmadi.');if(action==='confirm-pickup')courierModal('Restorandan olib ketish',`<p>#${esc(o.id.slice(0,12))} buyurtmaning barcha taomlarini qabul qildingizmi?</p><p class="metric-note">Tasdiqlangandan keyin sotuvchi panelida “Kuryerga berildi” va owner panelida “Yetkazilmoqda” ko‘rinadi.</p>`,'pickup-form',id);if(action==='confirm-deliver')courierModal('Yetkazishni yakunlash',`<p>Buyurtma mijozga topshirilganini tasdiqlang.</p>${o.payment==='Naqd'?`<div class="cash-summary">Mijozdan olinadigan summa: <strong>${money(courierTotal(o))} so‘m</strong>. Kuryer haqini alohida olmang.</div><label class="check"><input type="checkbox" name="cashConfirmed" required>Naqd to‘lovni to‘liq qabul qildim</label>`:''}<label class="check"><input type="checkbox" required>Buyurtmani mijozga topshirdim</label>`,'deliver-form',id);if(action==='confirm-release')courierModal('Buyurtmani takliflarga qaytarish','<p>Hali olib ketilmagan buyurtma yana boshqa kuryerlarga ko‘rinadi.</p>','release-form',id);if(action==='issue')courierModal('Muammoni belgilash','<div class="field"><label for="courier-issue">Muammo</label><textarea id="courier-issue" name="text" required minlength="3" maxlength="500" placeholder="Masalan, mijoz bilan bog‘lanib bo‘lmadi"></textarea></div><p class="metric-note">Izoh owner va sotuvchi panelida shu brauzerda ko‘rinadi. Dispetcherga xabar yuborilmaydi.</p>','issue-form',id);if(action==='detail')courierModal('Yetkazish tafsilotlari',`<p><strong>#${esc(o.id)}</strong> · ${esc(o.customer)}</p><p>${esc(o.deliveryAddress)}</p><div class="summary-line"><span>Olib ketilgan</span><strong>${courierDate(o.delivery.pickedUpAt)}</strong></div><div class="summary-line"><span>Yetkazilgan</span><strong>${courierDate(o.delivery.deliveredAt)}</strong></div><div class="summary-line"><span>Kuryer haqi</span><strong>${money(o.delivery.fee)} so‘m</strong></div><ul class="order-items">${o.items.map(i=>`<li>${i.qty} × ${esc(i.name)}</li>`).join('')}</ul>`);}catch(error){courierToast(error.message||'Amalni saqlab bo‘lmadi.');try{courierState=courierRead();courierRender();}catch{}}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(courierBusy||!f.reportValidity())return;const data=new FormData(f);const actions={'pickup-form':'pickup','deliver-form':'deliver','release-form':'release','issue-form':'issue','courier-profile':'profile'};const action=actions[f.id];if(!action)return;try{await courierRun(action,f.dataset.id,{cashConfirmed:data.has('cashConfirmed'),text:data.get('text'),issueType:data.get('issueType'),name:data.get('name'),phone:data.get('phone'),vehicle:data.get('vehicle')});courierClose();courierRender();courierToast(action==='deliver'?'Yetkazish yakunlandi. Demo daromad hisoblandi.':'O‘zgarishlar saqlandi.');}catch(error){f.querySelector('.form-error').textContent=error.message||'Saqlashda xatolik.';}});
document.addEventListener('change',e=>{if(e.target.id==='courier-person'){courierId=e.target.value;sessionStorage.setItem('lazzat-courier-id',courierId);courierClose();courierState=courierRead();courierRender();}if(e.target.id==='courier-period'){courierPeriod=e.target.value;courierRender();}if(e.target.id==='courier-branch'){courierBranch=e.target.value;courierRender();}});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay')&&!courierBusy)courierClose();});
document.addEventListener('keydown',e=>{if($('#overlay').hidden)return;if(e.key==='Escape'&&!courierBusy)courierClose();if(e.key==='Tab'){const items=[...$('#dialog').querySelectorAll('button,input,select,textarea,a[href]')],first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#dialog'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('storage',e=>{if(e.key!==COURIER_STORE)return;try{courierState=courierRead();if(!$('#overlay').hidden||courierPage==='profile'){courierToast('Buyurtmalar boshqa oynada yangilandi. Ochiq amalni bajarishda yangi holat tekshiriladi.');return;}courierRender();}catch(error){courierToast(error.message);}});
courierRender();
